107	     * Move a claim to the next status; a change its status does not allow is refused (409). Opening
108	     * gives the claim the sheet's next number, or its number within its period while the sheet numbers
109	     * by period (see {@link #takeNumber}); a voided claim keeps it (the number is never given again).
110	     * Opening records who opened it; that user cannot settle it (403).
111	     * Settling fixes the claim's due at its person's grade's rate in force on the claim's date, raised to
112	     * the sheet's floor, with its late charge added if it is overdue; later floor and late percent changes
113	     * leave it as fixed. Every rounding is half up for a claim dated before the sheet's policy date and
114	     * half to even otherwise; later policy date changes leave it as fixed too. A correction's due is its amount times that rate, rounded the same way, with no
115	     * floor and no late charge. A clerk
116	     * settling a claim whose due is above the sheet's clerk limit, if it has one, makes it PENDING instead
117	     * (CLAIM_PENDING), its due left live until a steward approves it; a claim with no due (no rate) is
118	     * refused (403), as it cannot be shown to be within the limit. A steward settles any claim.
119	     */
120	    @Transactional
121	    public Claim changeStatus(String sheetId, String user, Long claimId, ClaimStatus next) {
122	        // Lock the sheet before reading the claim, so claims opened at the same moment get different numbers
123	        // and a period closed at the same moment is seen.
124	        Sheet sheet = sheets.lock(sheetId)
125	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
126	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
127	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
128	        refuseIfClosed(sheetId, claim.getDate());
129	        if (!claim.getStatus().canBecome(next)) {
130	            throw new ResponseStatusException(HttpStatus.CONFLICT,
131	                    "A " + claim.getStatus() + " claim cannot become " + next);
132	        }
133	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
134	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
135	        }
136	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
137	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
138	        String number = next == ClaimStatus.OPEN ? takeNumber(sheet, claim.getDate()) : claim.getNumber();
139	        List<String> extra = new ArrayList<>();
140	        BigDecimal due = null;
141	        if (next == ClaimStatus.SETTLED) {
142	            due = dueNow(sheet, person, claim);
143	            if (overClerkLimit(sheet, user, due)) {
144	                next = ClaimStatus.PENDING;
145	            } else {
146	                extra.add("due=" + (due == null ? "n/a" : due.toPlainString()));
147	            }
148	        }
149	        claim.setStatus(next);
150	        claim.setNumber(number);
151	        if (next == ClaimStatus.OPEN) {
152	            claim.setOpenedBy(user);
153	        }
154	        if (next == ClaimStatus.SETTLED) {
155	            claim.setSettledDue(due);
156	        }
157	        record(switch (next) {
158	            case OPEN -> "CLAIM_OPENED";
159	            case PENDING -> "CLAIM_PENDING";
160	            case SETTLED -> "CLAIM_SETTLED";
161	            case VOID -> "CLAIM_VOIDED";
162	            case DRAFT -> throw new IllegalStateException();
163	        }, user, person, claim, number, extra);
