222	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim cannot be reassigned");
223	        }
224	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
225	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
226	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
227	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
228	        if (to.getId().equals(from.getId())) {
229	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already on " + to.getName());
230	        }
231	        if (claim.isCorrection()) {
232	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
233	                    "A correction corrects a claim of its own person, so it cannot be reassigned");
234	        }
235	        refuseIfRetired(to, claim.getDate());
236	        claim.setPersonId(to.getId());
237	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
238	                List.of("from=" + from.getName(), "to=" + to.getName()));
239	        return claim;
