242	    /** The PENDING claim a steward approves or rejects; refused otherwise (409, 403, 423). */
243	    private Claim pending(String sheetId, String user, Long claimId) {
244	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
245	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
246	        refuseIfClosed(sheetId, claim.getDate());
247	        if (claim.getStatus() != ClaimStatus.PENDING) {
248	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + claim.getStatus() + " claim is not pending");
249	        }
250	        if (roles.of(sheetId, user) != Role.STEWARD) {
251	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim");
252	        }
253	        return claim;
254	    }
