256	    /** The claim's due if it were settled now; null when its grade has no rate on its date. */
257	    private BigDecimal dueNow(Sheet sheet, Person person, Claim claim) {
258	        return sheet.liveDue(rates.inForce(sheet.getId(), person.gradeOn(claim.getDate()), claim.getDate())
259	                .map(rate -> sheet.dueAt(claim.getAmount(), rate.getRate(), claim.getDate()))
260	                .orElse(null), claim.getDate(), claim.isCorrection());
261	    }
