263	    /** How many of the selected claims a bulk open opened, and how many it refused. */
264	    public record BulkResult(int opened, int refused) {
265	    }
266	
267	    /**
268	     * Open the selected claims together, numbering them in list order: the people in the order they
269	     * were added, and within a person the newest claim (by date) first, claims of the same date in
270	     * the order they were added. A selected claim that cannot be opened (or is not on the sheet) is
271	     * refused and left as it is; the others are still opened.
272	     */
273	    @Transactional
274	    public BulkResult bulkOpen(String sheetId, String user, List<Long> claimIds) {
275	        sheets.lock(sheetId).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet"));
276	        Set<Long> selected = new HashSet<>(claimIds);
277	        Map<Long, Integer> personOrder = new HashMap<>();
278	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
279	        for (int i = 0; i < listed.size(); i++) {
280	            personOrder.put(listed.get(i).getId(), i);
281	        }
282	        List<Claim> ordered = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
283	                .filter(claim -> selected.contains(claim.getId()))
284	                .sorted(Comparator.<Claim>comparingInt(claim -> personOrder.getOrDefault(claim.getPersonId(), Integer.MAX_VALUE))
285	                        .thenComparing(Claim::getDate, Comparator.reverseOrder())
286	                        .thenComparing(Claim::getId))
287	                .toList();
288	        int opened = 0;
289	        for (Claim claim : ordered) {
290	            try {
291	                changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN);
292	                opened++;
293	            } catch (ResponseStatusException refused) {
294	                // Left as it is.
295	            }
296	        }
297	        return new BulkResult(opened, selected.size() - opened);
298	    }
299	
300	    /**
301	     * The number a claim corrects: for a negative amount, the number of a SETTLED claim of the same
302	     * person, refused (422) when none is named or it names no such claim; none for any other amount.
303	     */
304	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
305	        if (amount.signum() >= 0) {
306	            return null;
307	        }
308	        boolean settled = corrects != null && claims.findFirstBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
309	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED)
310	                .isPresent();
311	        if (!settled) {
312	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
313	                    "A negative amount must correct a settled claim of the same person");
314	        }
315	        return corrects;
316	    }
317	
318	    /**
319	     * The number a claim opened now is given: while the sheet numbers by period (its today on or after
320	     * its period numbering from), the next in the sequence of the period the claim's date is in,
321	     * &lt;period name&gt;-&lt;n&gt;, or X-&lt;n&gt; for a claim in no period; otherwise the sheet's next number.
322	     * The caller holds the sheet's lock.
323	     */
324	    private String takeNumber(Sheet sheet, LocalDate date) {
325	        if (!sheet.numbersByPeriod()) {
326	            return String.valueOf(sheet.takeClaimNumber());
327	        }
328	        String prefix = periods.findBySheetIdOrderByFromAsc(sheet.getId()).stream()
329	                .filter(period -> period.contains(date))
330	                .map(Period::getName)
331	                .findFirst()
332	                .orElse("X");
333	        ClaimSequence sequence = sequences.findById(new ClaimSequence.Key(sheet.getId(), prefix))
334	                .orElseGet(() -> sequences.save(new ClaimSequence(sheet.getId(), prefix)));
335	        return sequence.take();
336	    }
337	
338	    /**
339	     * Whether a clerk settling a claim of this due is above the sheet's clerk limit, so it goes PENDING;
340	     * refused (403) when the claim has no due, as it cannot be shown to be within the limit.
341	     */
342	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
343	        BigDecimal limit = sheet.getClerkLimit();
344	        if (limit == null || roles.of(sheet.getId(), user) != Role.CLERK) {
345	            return false;
346	        }
347	        if (due == null) {
348	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
349	                    "A clerk cannot settle a claim with no due while there is a clerk limit");
350	        }
351	        return due.compareTo(limit) > 0;
352	    }
353	
354	    /** Refuse (423) a change to a claim dated in a closed period. */
355	    private void refuseIfClosed(String sheetId, LocalDate date) {
356	        periods.findBySheetIdOrderByFromAsc(sheetId).stream()
357	                .filter(period -> period.isClosed() && period.contains(date))
358	                .findFirst()
359	                .ifPresent(period -> {
360	                    throw new ResponseStatusException(HttpStatus.LOCKED, "The period " + period.getName() + " is closed");
361	                });
362	    }
363	
364	    /** Refuse (422) a claim dated after its person's retirement date. */
365	    private static void refuseIfRetired(Person person, LocalDate date) {
366	        if (person.retiredOn(date)) {
367	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
368	                    person.getName() + " is retired from " + person.getRetiredFrom());
369	        }
370	    }
371	
372	    private void record(String event, String user, Person person, Claim claim) {
373	        record(event, user, person, claim, claim.getNumber(), List.of());
374	    }
375	
376	    /**
377	     * Amounts are written with two decimals, as shown, and dates as yyyy-mm-dd. A claim with a number adds number=&lt;number&gt;; any extra fields follow it.
378	     */
379	    private void record(String event, String user, Person person, Claim claim, String number, List<String> extra) {
380	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
381	                "amount=" + claim.getAmount().toPlainString(), "date=" + claim.getDate()));
382	        if (number != null) {
383	            fields.add("number=" + number);
384	        }
385	        fields.addAll(extra);
386	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
387	    }
388	
389	    private static BigDecimal scaled(BigDecimal amount) {
390	        return amount.setScale(2, RoundingMode.UNNECESSARY);
391	    }
392	}
