  protected due(claim: Claim): string {
    const cents = this.rates.dueOf(claim, gradeOn(this.grades(), claim.date));
    return cents === undefined ? 'n/a' : formatCents(cents);
  }

  /** The claim's due-by: its date plus the sheet's terms. */
  protected dueBy(claim: Claim): string {
    return dueBy(claim, this.session.terms() ?? 14);
  }

  /** Whether the claim is open (OPEN or PENDING) with its due-by before the sheet's today. */
  protected overdue(claim: Claim): boolean {
    return overdue(claim, this.session.terms() ?? 14, this.session.today() ?? '');
  }

  protected async act(claim: Claim, action: ClaimAction): Promise<void> {

  /**
   * Each person's overdue claims that count, by person id: how many, and their due figures added up
   * in cents, skipping those that are n/a.
   */
  private readonly overdueByPerson = computed(() => {
    const terms = this.session.terms() ?? 14;
    const today = this.session.today() ?? '';
    const out = new Map<number, { count: number; cents: number }>();
    for (const p of this.people()) {
      const late = this.claims.all().filter((c) => c.personId === p.id && counts(c, p) && overdue(c, terms, today));
      out.set(p.id, {
        count: late.length,
        cents: late.map((c) => this.rates.dueOf(c, gradeOn(p.grades, c.date)) ?? 0).reduce((sum, c) => sum + c, 0),
      });
    }
    return out;
  });

